describe('File Upload Button Disabled During Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should disable upload button while file is uploading', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: { success: true, message: 'File uploaded successfully' }
    }).as('uploadFile');

    // Verify upload button is visible and enabled initially
    cy.get('[data-testid="upload-button"]').should('be.visible');
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Click the upload button to start the upload
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload button is now disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify upload progress indicator is visible
    cy.get('[data-testid="upload-progress-indicator"]').should('be.visible');

    // Wait for the upload API call to complete
    cy.wait('@uploadFile');

    // Verify upload button is re-enabled after completion
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');
  });

  it('should re-enable upload button after canceling upload', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: { success: false, message: 'Upload cancelled' }
    }).as('cancelUpload');

    // Verify upload button is visible and enabled initially
    cy.get('[data-testid="upload-button"]').should('be.visible');
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Click the upload button to start the upload
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload button is now disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify upload progress indicator is visible
    cy.get('[data-testid="upload-progress-indicator"]').should('be.visible');

    // Click cancel button to cancel the upload
    cy.get('[data-testid="cancel-upload-button"]').click();

    // Verify upload button is re-enabled after cancellation
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify cancel success message appears
    cy.get('[data-testid="cancel-success-message"]').should('be.visible');
    cy.get('[data-testid="cancel-success-message"]').should('contain', 'Upload cancelled');
  });
});
